using System;using System.Collections;using System.Collections.Generic;using System.IO;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [Serializable] public class R17ContactRow{public string id,launch,initial,final,contacts;public List<BreakRecord> actualBreaks=new List<BreakRecord>();}
 [Serializable] public class R17ContactReport{public string state="RUNNING",method="Saved accepted launch initialization. One ordinary captured input, angle+1 neighbor, strong contact allocation only 40/28; no pose overwrite or broad repeat.";public List<R17ContactRow> rows=new List<R17ContactRow>();}
 [UnityTest]public IEnumerator R17Contacts(){Directory.CreateDirectory(Evidence);var path=Path.Combine(Evidence,"contact-probe.json");Assert.That(File.Exists(path),Is.False);var report=new R17ContactReport();Action save=()=>File.WriteAllText(path,JsonUtility.ToJson(report,true));save();var inputs=Environment.GetEnvironmentVariable("CRAB_R17_INPUT_DIR");
 foreach(var id in (Environment.GetEnvironmentVariable("CRAB_EVIDENCE_SCOPE")=="phase01"?new[]{"ordinary02-phase90","ordinary02-phase180","ordinary02-phase270"}:new[]{"ordinary02","ordinary02-angle16","strong40","strong28"})){yield return NewRetrySubject(false,true,true,true,true,true,true);string launch=File.ReadAllText(Path.Combine(inputs,id.StartsWith("strong")?"strong-accepted-launch.json":"ordinary02-accepted-launch.json"));if(id.EndsWith("angle16")){var receipt=JsonUtility.FromJson<R17Launch>(launch);var settings=JsonUtility.FromJson<InputSpec>(receipt.settingsJson);settings.angle=16;receipt.settingsJson=JsonUtility.ToJson(settings);launch=JsonUtility.ToJson(receipt);}if(id.Contains("-phase")){var receipt=JsonUtility.FromJson<R17Launch>(launch);receipt.phase+=float.Parse(id.Substring(id.LastIndexOf("phase")+5));launch=JsonUtility.ToJson(receipt);}Call(current,"ReviewReplayAccepted",launch);var sim=Property(current,"ReviewSimulation");var row=new R17ContactRow{id=id,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt")),initial=(string)Call(sim,"LaunchBodyReceipt")};report.rows.Add(row);if(id=="strong28")sim.GetType().GetField("ReviewContactSpinLimitR17").SetValue(sim,28f);save();
 for(int i=0;i<11000&&!(bool)Property(current,"Finished");i++)Call(current,"Tick",1f/60);row.final=JsonUtility.ToJson(State(current));row.contacts=(string)Call(sim,"ReviewContactTraceJson");foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.actualBreaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});save();Assert.That((bool)Property(current,"Finished"),Is.True);Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="OBSERVATION_COMPLETE_NOT_ADOPTION";save();}
 [Serializable]public class R17Launch{public string source,settingsJson,bodyJson;public int direction;public float spin,charge,phase;}
}
